#!/usr/bin/env bash
set -euo pipefail
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"; source "$SCRIPT_DIR/network_discovery.sh"; REPORT=${1:?Uso: $0 <pasta_do_relatorio>}; mkdir -p "$REPORT"; LAN=$(select_lan_interface); IFACE_WLAN=$(select_wireless_audit_interface); [[ "$IFACE_WLAN" != "$LAN" ]] || { fail 'Adaptador de auditoria não pode ser a interface LAN selecionada'; exit 1; }; record_interface_selection "$REPORT" "$LAN" "$(select_scan_range "$LAN" "${SCAN_RANGE:-}")"; printf 'wireless_interface=%s\n' "$IFACE_WLAN" >> "$REPORT/interface-selection.txt"; sudo airmon-ng start "$IFACE_WLAN"; MON=$(iw dev | awk '/Interface/{i=$2} /type monitor/{print i; exit}'); [[ -n "$MON" ]] || { fail 'Adaptador não entrou em modo monitor'; exit 1; }; trap 'sudo airmon-ng stop "$MON" >/dev/null 2>&1 || true' EXIT; sudo timeout 130 airodump-ng "$MON" --output-format csv --write "$REPORT/wifi"; timeout 45 sudo wash -i "$MON" | tee "$REPORT/wps.txt"; test -s "$REPORT/wifi-01.csv"; test -s "$REPORT/wps.txt"